SELECT SQL_CALC_FOUND_ROWS wptests_users.ID
				 FROM wptests_users INNER JOIN wptests_usermeta ON ( wptests_users.ID = wptests_usermeta.user_id )  INNER JOIN wptests_usermeta AS mt1 ON ( wptests_users.ID = mt1.user_id )
				 WHERE 1=1 AND ( 
  ( 
    ( 
      ( 
        ( 
          ( wptests_usermeta.meta_key = 'wptests_capabilities' AND wptests_usermeta.meta_value LIKE '%\"install\\_plugins\"%' ) 
          OR 
          ( wptests_usermeta.meta_key = 'wptests_capabilities' AND wptests_usermeta.meta_value LIKE '%\"administrator\"%' )
        )
      )
    ) 
    AND 
    ( 
      mt1.meta_key = 'wptests_capabilities'
    )
  )
)
				 ORDER BY user_login ASC

